"""Map Jev's typed answers + confidence thresholds to ALLOW / BLOCK / ESCALATE.

Rules are evaluated in severity order. Every rule that fires adds a
human-readable reason, and the most severe verdict wins:

  BLOCK     P(safe) is very low, the impact is rated critical, or Jev
            confidently puts the action in a dangerous risk category.
  ESCALATE  Jev is not confident, the action is not clearly safe, the
            impact is serious, the action looks off-task and could change
            something, or the content being written looks poor.
  ALLOW     none of the above. An off-task action with negligible impact
            (an agent reading around while it investigates) is allowed, and
            the reason says so.
"""

from __future__ import annotations

from dataclasses import dataclass

from .config import Thresholds
from .models import JevSignals, Verdict

DANGEROUS_RISKS = {"data_loss", "exfiltration", "system_damage"}
RISK_LABELS = {
    "none": "no meaningful risk",
    "data_loss": "data loss",
    "exfiltration": "data exfiltration",
    "system_damage": "system damage",
    "unclear": "unclear effects",
}
SEVERITY_LABELS = ["negligible", "minor", "serious", "critical"]


@dataclass(frozen=True)
class PolicyResult:
    verdict: Verdict
    confidence: float
    reasons: list[str]


def severity_label(score: float) -> str:
    return SEVERITY_LABELS[max(0, min(3, round(score)))]


def decide(s: JevSignals, t: Thresholds) -> PolicyResult:
    block: list[str] = []
    escalate: list[str] = []
    risk_p = s.risk_probabilities.get(s.risk, 0.0)

    if s.p_safe < t.block_safe_below:
        block.append(f"Jev rates this action unsafe (P(safe) = {s.p_safe:.2f}).")
    if s.severity >= t.severity_block:
        block.append(f"Potential impact rated {severity_label(s.severity)} ({s.severity:.1f} / 3).")
    if s.risk in DANGEROUS_RISKS and risk_p >= t.risk_block:
        block.append(f"Classified as {RISK_LABELS[s.risk]} risk (p = {risk_p:.2f}).")

    if s.confidence < t.min_confidence:
        escalate.append(f"Jev is uncertain about this action (confidence {s.confidence:.2f}).")
    if t.block_safe_below <= s.p_safe < t.allow_safe_above:
        escalate.append(f"Not confidently safe (P(safe) = {s.p_safe:.2f}).")
    if t.severity_escalate <= s.severity < t.severity_block:
        escalate.append(f"Potential impact rated {severity_label(s.severity)} ({s.severity:.1f} / 3).")
    off_task = s.p_on_task < t.on_task_min
    if off_task and s.severity >= t.off_task_severity:
        escalate.append(f"Looks unrelated to the agent's task (P(on task) = {s.p_on_task:.2f}).")
    if s.output_ok is not None and s.output_ok < t.output_ok_min:
        escalate.append(f"Content being written looks incomplete or wrong (P(ok) = {s.output_ok:.2f}).")
    if s.risk == "unclear" and not block:
        escalate.append(f"Effects cannot be determined from the request (p = {risk_p:.2f}).")

    if block:
        return PolicyResult("BLOCK", s.confidence, block + escalate)
    if escalate:
        return PolicyResult("ESCALATE", s.confidence, escalate)
    reasons = [f"Jev rates this action safe (P(safe) = {s.p_safe:.2f}, impact {severity_label(s.severity)})."]
    if off_task:
        reasons.append(f"It looks unrelated to the task (P(on task) = {s.p_on_task:.2f}), but its impact is "
                       f"{severity_label(s.severity)}, so it doesn't need a human.")
    return PolicyResult("ALLOW", s.confidence, reasons)
"""SQLite decision history. One row per decision, stored as JSON."""

from __future__ import annotations

import sqlite3
import threading
from pathlib import Path

from .models import Decision


class DecisionStore:
    def __init__(self, path: Path):
        path.parent.mkdir(parents=True, exist_ok=True)
        self._lock = threading.Lock()
        self._db = sqlite3.connect(path, check_same_thread=False)
        self._db.execute("PRAGMA journal_mode=WAL")
        self._db.execute(
            "CREATE TABLE IF NOT EXISTS decisions (id TEXT PRIMARY KEY, created_at REAL NOT NULL, data TEXT NOT NULL)"
        )
        self._db.execute("CREATE INDEX IF NOT EXISTS idx_created ON decisions(created_at)")
        self._db.commit()

    def save(self, d: Decision) -> None:
        with self._lock:
            self._db.execute(
                "INSERT INTO decisions (id, created_at, data) VALUES (?, ?, ?) "
                "ON CONFLICT(id) DO UPDATE SET data = excluded.data",
                (d.id, d.created_at, d.model_dump_json()),
            )
            self._db.commit()

    def get(self, decision_id: str) -> Decision | None:
        with self._lock:
            row = self._db.execute("SELECT data FROM decisions WHERE id = ?", (decision_id,)).fetchone()
        return Decision.model_validate_json(row[0]) if row else None

    def list(self, limit: int = 200) -> list[Decision]:
        with self._lock:
            rows = self._db.execute(
                "SELECT data FROM decisions ORDER BY created_at DESC LIMIT ?", (limit,)
            ).fetchall()
        return [Decision.model_validate_json(r[0]) for r in rows]

    def clear(self) -> None:
        with self._lock:
            self._db.execute("DELETE FROM decisions")
            self._db.commit()

    def close(self) -> None:
        with self._lock:
            self._db.close()
"""In-process fan-out of decision events to SSE subscribers."""

from __future__ import annotations

import asyncio
import json
from typing import Any


def sse(event: str, data: Any) -> str:
    return f"event: {event}\ndata: {json.dumps(data, default=str)}\n\n"


class EventBroker:
    def __init__(self) -> None:
        self._subscribers: set[asyncio.Queue[str]] = set()

    def subscribe(self) -> asyncio.Queue[str]:
        queue: asyncio.Queue[str] = asyncio.Queue(maxsize=500)
        self._subscribers.add(queue)
        return queue

    def unsubscribe(self, queue: asyncio.Queue[str]) -> None:
        self._subscribers.discard(queue)

    def publish(self, event: str, data: Any) -> None:
        message = sse(event, data)
        for queue in list(self._subscribers):
            try:
                queue.put_nowait(message)
            except asyncio.QueueFull:  # a stalled client; drop it rather than block everyone
                self._subscribers.discard(queue)

