import re
for path in ["docs/ARCHITECTURE.md", "docs/ARCHITECTURE-LOW-LEVEL.md"]:
    text = open(path, encoding="utf-8").read()
    # strip fenced blocks
    body = re.sub(r"```.*?```", "", text, flags=re.S)
    for n, line in enumerate(body.splitlines(), 1):
        stripped = re.sub(r"`[^`]*`", "", line)
        if re.search(r"(?<!\\)<[A-Za-z/]", stripped):
            print(path, "ANGLE", line[:120])
        if line.startswith("|"):
            spans = re.findall(r"`[^`]*`", line)
            if any("|" in s for s in spans):
                print(path, "PIPE-IN-CODE", line[:120])
    # anchors
    heads = {}
    for h in re.findall(r"^#{1,6} (.+)$", re.sub(r"```.*?```", "", text, flags=re.S), flags=re.M):
        a = re.sub(r"[^\w\- ]", "", h.lower()).replace(" ", "-")
        heads[a] = h
    for a in re.findall(r"\]\(#([^)]+)\)", text):
        if a not in heads:
            print(path, "BAD ANCHOR", a)
print("done")
EOF

